def solve(x, a, b, alpha):
    r=len(a)
    if not x or not r or not b or any(len(row)!=len(x) for row in a) or any(len(row)!=r for row in b):
        raise ValueError('shape')
    z=[sum(v*w for v,w in zip(row,x)) for row in a]
    return [alpha/r*sum(v*w for v,w in zip(row,z)) for row in b]

